/*
 * golden.c - on-target verification of the exported model.
 *
 * src/model/golden_vectors.h (generated by tools/ml/train.py) embeds held-out
 * TEST windows (raw IMU counts + gyro bias), the float32 features computed by
 * the Python mirror and the class predicted by the Python tree. This command
 * runs the same windows through the firmware's features.c + model tree on the
 * STM32 and reports, per window, the class agreement, the maximum absolute
 * feature difference, and the cycle count. A placeholder build says so.
 */
#include "app.h"
#include "bsp.h"
#include "model_infer.h"
#include "golden_vectors.h"
#include <math.h>

static float s_gscratch[SIG_FEATURE_SCRATCH(SIG_WINDOW_SAMPLES)];   /* console task only */

void golden_run(void)
{
    uint32_t agree = 0, correct = 0, feat_exact = 0;
    float worst = 0.0f;
    uint32_t cyc_min = UINT32_MAX, cyc_max = 0;
    uint64_t cyc_sum = 0;
    sig_log("#GOLDEN,START,count=%d,model=%s,placeholder=%d,source=%s", SIG_GOLDEN_COUNT, sig_model_version(),
            sig_model_is_placeholder(), SIG_GOLDEN_SOURCE);
    for (int i = 0; i < SIG_GOLDEN_COUNT; i++) {
        const sig_golden_t *g = &sig_golden[i];
        float f[SIG_N_FEATURES];
        sig_prediction_t p;
        uint32_t c0 = sig_cycles();
        sig_features_compute(g->samples, SIG_WINDOW_SAMPLES, g->bias, f, s_gscratch);
        bool ok = sig_model_predict(f, &p);
        uint32_t cyc = sig_cycles() - c0;
        float maxdiff = 0.0f;
        for (int k = 0; k < SIG_N_FEATURES; k++) {
            float d = fabsf(f[k] - g->features[k]);
            if (d > maxdiff) maxdiff = d;
        }
        if (maxdiff == 0.0f) feat_exact++;
        if (maxdiff > worst) worst = maxdiff;
        bool same = ok && p.cls == g->python_pred;
        agree += same;
        correct += ok && p.cls == g->label;
        cyc_sum += cyc;
        if (cyc < cyc_min) cyc_min = cyc;
        if (cyc > cyc_max) cyc_max = cyc;
        sig_log("#GOLDEN,%d,%s,label=%s,python=%s,target=%s,match=%d,max_feat_abs_diff=%.9f,cycles=%lu", i, g->id,
                sig_class_short(g->label), sig_class_short(g->python_pred), sig_class_short(p.cls), same,
                (double)maxdiff, (unsigned long)cyc);
        if ((i & 7) == 7) xEventGroupSetBits(g_alive, ALIVE_CONSOLE);
    }
    uint32_t mhz = SystemCoreClock / 1000000u;
    sig_log("#GOLDEN,SUMMARY,count=%d,python_target_agree=%lu,target_correct=%lu,features_bit_exact=%lu,"
            "worst_feat_abs_diff=%.9f,cycles_min=%lu,cycles_mean=%lu,cycles_max=%lu,us_mean=%lu",
            SIG_GOLDEN_COUNT, (unsigned long)agree, (unsigned long)correct, (unsigned long)feat_exact, (double)worst,
            (unsigned long)cyc_min, (unsigned long)(SIG_GOLDEN_COUNT ? cyc_sum / SIG_GOLDEN_COUNT : 0),
            (unsigned long)cyc_max, (unsigned long)(SIG_GOLDEN_COUNT ? cyc_sum / SIG_GOLDEN_COUNT / mhz : 0));
}
